SELECT 
FROM opc_crm_opportunity

    deleted = 0
    AND owner_id = #{ownerId}
    AND stage = #{stage}
    AND customer_id = #{customerId}

ORDER BY create_time DESC

SELECT 
FROM opc_crm_opportunity

    deleted = 0
    AND owner_id = #{ownerId}

ORDER BY score DESC, amount DESC
LIMIT #{limit}

SELECT COUNT(*) FROM opc_crm_opportunity

    deleted = 0
    AND owner_id = #{ownerId}
    AND stage = #{stage}

SELECT COALESCE(SUM(amount), 0) FROM opc_crm_opportunity

    deleted = 0
    AND owner_id = #{ownerId}

        AND stage IN
        #{stage}
